INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(73192, 'koKR', '', '', 19865),
(73210, 'koKR', '', '', 19865),
(73215, 'koKR', '감히 나의 새로운 보금자리에 침입한 게 어떤 녀석이? 서리늑대의 애완동물인가?', '', 19865),
(73216, 'koKR', '잠깐, 이건 서리늑대가 아니잖아.', '', 19865),
(73217, 'koKR', '그냥 없애 버려! 어디, 맛이 어떤지 한번 보자!', '', 19865),
