INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(89285, 'koKR', '더는... 무리야...', '', 19865),
(89286, 'koKR', '어둠이... 날 부르는군...', '', 19865),
(89287, 'koKR', '너의 최후를 직시해라.', '', 19865),
(89288, 'koKR', '내가 너의 최후다.', '', 19865),
(89289, 'koKR', '너의 미래는... 아주 짧다.', '', 19865),
(89290, 'koKR', '나의 고통을 그대로 겪어라.', '', 19865),
(89291, 'koKR', '크아라악!', '', 19865),
(89292, 'koKR', '넌 고통에 대해 아무것도 몰라.', '', 19865),
(89293, 'koKR', '꺼져라!', '', 19865),
(89294, 'koKR', '고통으로 몸부림쳐라.', '', 19865),
